        const p = d.focal ? 1 : easeOutBack(clamp2((t - CT.reveal0 - Math.hypot(d.x - R0.x, d.z - R0.z) / 120 * 2.4) / 0.9), 1.25);
        d.r.group.visible = p > 1e-3;
        d.r.group.scale.setScalar(Math.max(1e-4, p));
