    lk(roundedPath([up(eP, 1.2), up(eP, 1.2).add(new Vector3(0, 0, 0)), up(at(LY.ex, D32, TIERS.T3.y - 6), 0), up(at(LY.fn.l, D32, TIERS.T2.y + 8), 0), up(pFn, 5.5)], 3), "hierarchie", 80.6, {});
    lk(roundedPath([up(eP, 1.2), up(at(LY.ex, D32, TIERS.T3.y - 6), 0), up(at(LY.intl.l, D32, TIERS.T2.y + 8), 0), up(pIn, 8.4)], 3), "hierarchie", 80.8, {});
    const pM1 = at(LY.mk[0], TIERS.T1.d, TIERS.T1.y), pM2 = at(LY.mk[1], TIERS.T1.d, TIERS.T1.y);
    lk(roundedPath([up(pIn, 1), up(at(LY.intl.l, D21, TIERS.T1.y + 4), 0), up(at(LY.mk[0], D21, TIERS.T1.y + 4), 0), up(pM1, 4.8)], 2.4), "hierarchie", 81.1, {});
    lk(roundedPath([up(pIn, 1), up(at(LY.intl.l, D21, TIERS.T1.y + 4), 0), up(at(LY.mk[1], D21, TIERS.T1.y + 4), 0), up(pM2, 4.8)], 2.4), "hierarchie", 81.2, {});
    const pr5 = restSlots[4], pr6 = restSlots[5];
