    lk(roundedPath([up(pM2, 1), up(at(LY.mk[1], D10, 5), 0), up(pr6, 3.6)], 2.4), "hierarchie", 81.6, {});
    restSlots.forEach((p, k) => lk(roundedPath([up(p, 3.4), up(p.clone().addScaledVector(uB, -4.2), 1)], 1), "hierarchie", 82.6 + k * 0.1, { radius: 0.09, drawDur: 0.7 }));
    const trunkEnd = at(LY.trunkEnd, TIERS.T1.d + 6, TIERS.T1.y + 8);
