    lk(new CatmullRomCurve3([up(at(tA, TIERS.T3.d, TIERS.T3.y), 9), up(at(tB, dTop + 4, TIERS.T3.y), 11), up(at(tC, dTop - 6, TIERS.T3.y), 8), up(at(tD, (TIERS.T3.d + TIERS.T1.d) / 2, (TIERS.T3.y + TIERS.T1.y) / 2 + 4), 0), up(at((tD + LY.trunkEnd) / 2 + 4, TIERS.T1.d + 12, TIERS.T1.y + 9), 0), trunkEnd]), "contrat", 81.9, { radius: 0.17, drawDur: 1.8 });
