          const d = dotsGeo[i];
          const delay = 0.5 * (1 - d.rho);
          const u = easeInOutCubic(clamp2((m - delay) / (1 - 0.5)));
          const appear = easeOutBack(clamp2((t - G_T.dots0 - d.rho * 1.1) / 0.5), 2.2);
          tmpP.copy(d.F).lerp(tmpS.copy(d.v).multiplyScalar(R * 0.995), u);
